suppressPackageStartupMessages({library(readxl);library(dplyr)})
source(file.path(dirname(sub("^--file=", "", commandArgs(FALSE)[grepl("^--file=", commandArgs(FALSE))][1])), "_common.R"))
base<-read_excel(resolve_data_path(),sheet="Baseline_191")%>%select(Study_ID,Baseline_Pain=Pain_Present);fu<-read_excel(resolve_data_path(),sheet="First_FU_191")%>%select(Study_ID,First_FU_Pain=Pain_Present);dat<-read_excel(resolve_data_path(),sheet="Baseline_to_FirstFU")%>%left_join(base,by="Study_ID")%>%left_join(fu,by="Study_ID")
groups<-list(list("Overall",NULL),list("Mild pain (VAS 0–3)",MILD),list("Moderate-to-severe pain (VAS ≥4)",MODSEV))
pa<-list();raw<-c();for(g in groups){z<-if(is.null(g[[2]]))dat else dat%>%filter(Baseline_Pain_Group_2L==g[[2]]);z<-z%>%filter(!is.na(Baseline_Pain),!is.na(First_FU_Pain));imp<-sum(z$Baseline_Pain==1&z$First_FU_Pain==0);wor<-sum(z$Baseline_Pain==0&z$First_FU_Pain==1);disc<-imp+wor;p<-if(disc==0)1 else binom.test(min(imp,wor),disc,p=.5)$p.value;raw<-c(raw,p);pa[[length(pa)+1]]<-data.frame(Outcome="Pain present",Baseline_pain_group=g[[1]],n=nrow(z),Baseline_n_pct=sprintf("%d (%.1f)",sum(z$Baseline_Pain==1),100*mean(z$Baseline_Pain==1)),First_follow_up_n_pct=sprintf("%d (%.1f)",sum(z$First_FU_Pain==1),100*mean(z$First_FU_Pain==1)),Improved_n=imp,Worsened_n=wor,P_value=fmt_p(p),check.names=FALSE)};adj<-p.adjust(raw,"BH");for(i in seq_along(pa))pa[[i]]$FDR_adjusted_P_value<-fmt_p(adj[i]);panelA<-bind_rows(pa)
metrics<-list(c("VAS change","VAS_Response_FirstFU"),c("Pain-burden change","Pain_Burden_Response_FirstFU"));tests<-sapply(metrics,function(m)chisq.test(table(dat[[m[2]]],dat$Baseline_Pain_Group_2L),correct=FALSE)$p.value);ad2<-p.adjust(tests,"BH");pb<-list();for(i in seq_along(metrics)){m<-metrics[[i]];for(g in groups){z<-if(is.null(g[[2]]))dat else dat%>%filter(Baseline_Pain_Group_2L==g[[2]]);n<-nrow(z);cc<-table(factor(z[[m[2]]],levels=CHANGE_LEVELS));pb[[length(pb)+1]]<-data.frame(Change_metric=m[1],Baseline_pain_group=g[[1]],n=n,Decreased_n_pct=sprintf("%d (%.1f)",cc[1],100*cc[1]/n),Maintained_n_pct=sprintf("%d (%.1f)",cc[2],100*cc[2]/n),Increased_n_pct=sprintf("%d (%.1f)",cc[3],100*cc[3]/n),Decreased_or_maintained_n_pct=sprintf("%d (%.1f)",cc[1]+cc[2],100*(cc[1]+cc[2])/n),Between_group_P_value=if(g[[1]]=="Overall")fmt_p(tests[i]) else "",FDR_adjusted_P_value=if(g[[1]]=="Overall")fmt_p(ad2[i]) else "",check.names=FALSE)}};panelB<-bind_rows(pb)
write.csv(panelA,file.path(output_dir(),"Supplementary_Table_S5_Panel_A.csv"),row.names=FALSE,fileEncoding="UTF-8");write.csv(panelB,file.path(output_dir(),"Supplementary_Table_S5_Panel_B.csv"),row.names=FALSE,fileEncoding="UTF-8");print(panelA);print(panelB)
